def fill_hollow_interiors(grid):
    """Fill hollow interiors based on shape boundaries."""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    result = [row[:] for row in grid]

    # Find all 5 components and their bounding boxes
    visited_boundary = set()
    components = []  # list of (min_r, max_r, min_c, max_c)

    def get_component(start_r, start_c):
        comp = []
        stack = [(start_r, start_c)]
        comp_set = set([(start_r, start_c)])
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in comp_set and grid[nr][nc] == 5:
                    comp_set.add((nr, nc))
                    stack.append((nr, nc))
        visited_boundary.update(comp_set)
        return comp_set

    # Find all 5 components
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5 and (r, c) not in visited_boundary:
                comp_set = get_component(r, c)
                if len(comp_set) > 0:
                    min_r, max_r = min(x[0] for x in comp_set), max(x[0] for x in comp_set)
                    min_c, max_c = min(x[1] for x in comp_set), max(x[1] for x in comp_set)
                    # Check if interior has 0s (not on grid edge)
                    has_interior = any(
                        1 <= ir < rows - 1 and 1 <= ic < cols - 1
                        and 0 <= ir < rows and 0 <= ic < cols
                        and grid[ir][ic] == 0
                        for ir in range(min_r + 1, max_r)
                        for ic in range(min_c + 1, max_c)
                    )
                    if has_interior:
                        components.append((min_r, max_r, min_c, max_c))

    # For each component, fill ALL 0s strictly inside the bounding box
    # (i.e., min_r < r < max_r and min_c < c < max_c)
    for min_r, max_r, min_c, max_c in components:
        for r in range(min_r + 1, max_r):
            for c in range(min_c + 1, max_c):
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == 0:
                    result[r][c] = 2

    return result

